// Command wordfreq prints the 10 most frequent ASCII words read from standard input.
package main

import (
	"bufio"
	"fmt"
	"os"
)

const topN = 10

func main() {
	counts, err := CountWords(os.Stdin)
	if err != nil {
		fmt.Fprintln(os.Stderr, "wordfreq:", err)
		os.Exit(1)
	}

	out := bufio.NewWriter(os.Stdout)
	for _, wc := range TopWords(counts, topN) {
		fmt.Fprintf(out, "%d %s\n", wc.Count, wc.Word)
	}
	if err := out.Flush(); err != nil {
		fmt.Fprintln(os.Stderr, "wordfreq:", err)
		os.Exit(1)
	}
}

package main

import (
	"cmp"
	"errors"
	"io"
	"slices"
)

const bufferSize = 64 * 1024

// WordCount pairs a lowercase word with its number of occurrences.
type WordCount struct {
	Word  string
	Count int
}

// lowerASCII reports whether b is an ASCII letter and returns its lowercase form.
func lowerASCII(b byte) (byte, bool) {
	switch {
	case 'a' <= b && b <= 'z':
		return b, true
	case 'A' <= b && b <= 'Z':
		return b + ('a' - 'A'), true
	default:
		return 0, false
	}
}

// CountWords streams r and returns the number of occurrences of each word,
// where a word is a maximal run of ASCII letters folded to lowercase.
func CountWords(r io.Reader) (map[string]int, error) {
	counts := make(map[string]int)
	buf := make([]byte, bufferSize)
	word := make([]byte, 0, 64)

	for {
		n, err := r.Read(buf)
		for _, b := range buf[:n] {
			if c, ok := lowerASCII(b); ok {
				word = append(word, c)
			} else if len(word) > 0 {
				counts[string(word)]++ // the conversion does not allocate for existing keys
				word = word[:0]
			}
		}
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, err
		}
	}
	if len(word) > 0 {
		counts[string(word)]++
	}
	return counts, nil
}

// compareWordCounts orders by count descending, then word ascending.
func compareWordCounts(a, b WordCount) int {
	if c := cmp.Compare(b.Count, a.Count); c != 0 {
		return c
	}
	return cmp.Compare(a.Word, b.Word)
}

// TopWords returns up to n entries of counts, most frequent first,
// with ties broken by word in ascending byte order.
func TopWords(counts map[string]int, n int) []WordCount {
	if n <= 0 {
		return nil
	}
	// Keep a small sorted slice of the best n entries seen so far.
	top := make([]WordCount, 0, n+1)
	for w, c := range counts {
		wc := WordCount{Word: w, Count: c}
		if len(top) == n && compareWordCounts(wc, top[n-1]) >= 0 {
			continue
		}
		i, _ := slices.BinarySearchFunc(top, wc, compareWordCounts)
		top = slices.Insert(top, i, wc)
		if len(top) > n {
			top = top[:n]
		}
	}
	return top
}

package main

import (
	"slices"
	"strings"
	"testing"
)

func TestCountWordsAndTop(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want []WordCount
	}{
		{"simple", "The cat and the hat.", []WordCount{{"the", 2}, {"and", 1}, {"cat", 1}, {"hat", 1}}},
		{"empty", "", nil},
		{"separators", "don't stop_me 4now, now-NOW\xff\xc3(x", []WordCount{
			{"now", 3}, {"don", 1}, {"me", 1}, {"stop", 1}, {"t", 1}, {"x", 1},
		}},
		{"limit", "k j i h g f e d c b a a", []WordCount{
			{"a", 2}, {"b", 1}, {"c", 1}, {"d", 1}, {"e", 1}, {"f", 1}, {"g", 1}, {"h", 1}, {"i", 1}, {"j", 1},
		}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			counts, err := CountWords(strings.NewReader(tt.in))
			if err != nil {
				t.Fatal(err)
			}
			got := TopWords(counts, topN)
			if !slices.Equal(got, tt.want) && !(len(got) == 0 && len(tt.want) == 0) {
				t.Errorf("got %v, want %v", got, tt.want)
			}
		})
	}
}
